contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We rely only on public functions and address(c).balance. We will:
    // 1) deposit some amount (param amount)
    // 2) record balances before withdraw
    // 3) call withdrawAll and record whether it reverted
    // 4) if it didn't revert, call withdrawAll again and record whether second call reverts and whether it transfers any Ether (by observing address(c).balance change)
    // The asserted invariant:
    // If the first withdrawAll succeeded then (A) the second withdrawAll must not succeed in transferring any additional Ether (i.e., either it reverts or it does not change address(c).balance), and (B) it is impossible for the first withdrawAll to have succeeded while address(c).balance stayed the same if there was a positive deposit amount.

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance for deposit");

        uint beforeC = address(c).balance;
        // perform deposit of `amount` into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterDepositC = address(c).balance;

        // Deposit must increase c's balance by amount (we don't assert that here since it's an accepted rule),
        // but capture the presumed recorded credit > 0 when amount>0.

        // Call withdrawAll and observe whether it reverts
        bool firstReverted = true;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }
        uint afterFirstC = address(c).balance;

        // Now call withdrawAll a second time and observe whether it reverts
        bool secondReverted = true;
        uint afterSecondC = afterFirstC;
        // try-catch must be top-level call
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
            afterSecondC = address(c).balance;
        } else {
            secondReverted = false;
            afterSecondC = address(c).balance;
        }

        // If first withdraw succeeded and the deposit amount was > 0, then (1) the first call must have decreased c's balance (i.e., afterFirstC < afterDepositC),
        // and (2) the second call must not further transfer Ether to this contract: either it reverts or it leaves c's balance unchanged.
        assert(
            !(firstReverted == false && amount > 0 && afterFirstC >= afterDepositC) &&
            !(firstReverted == false && secondReverted == false && afterSecondC < afterFirstC)
        );
    }

    // Allow receiving Ether when withdrawAll sends funds.
    receive() external payable {}
}

