// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeC = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        bool firstReverted = true;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint afterFirstC = address(c).balance;
        bool secondReverted = true;
        uint afterSecondC = afterFirstC;
        try c.withdrawAll() {
            secondReverted = false;
            afterSecondC = address(c).balance;
        } catch {
            secondReverted = true;
            afterSecondC = address(c).balance;
        }
        assertTrue(!(firstReverted == false && amount > 0 && afterFirstC >= afterDepositC) &&
            !(firstReverted == false && secondReverted == false && afterSecondC < afterFirstC));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
